export interface DefinitionLookup {
  hasDefinition: (key: string) => boolean;
  hasDefinitions: () => boolean;
}

/** One-shot resolution requires membership; documents additionally track removals. */
export class DefinitionIndex implements DefinitionLookup {
  protected counts = new Map<string, number>();
  clear(): void {
    this.counts.clear();
  }

  declare(_node: object, key: string): void {
    this.counts.set(key, 1);
  }

  hasDefinition(key: string): boolean {
    return this.counts.has(key);
  }

  hasDefinitions(): boolean {
    return this.counts.size > 0;
  }
}

