import { describe, expect, it } from "vitest";
import { createParser } from "../packages/satorigear/src/index.ts";

const parser = createParser({ features: { math: true } });
const endings = {
  LF: ["\n", "\n", "\n"],
  CRLF: ["\r\n", "\r\n", "\r\n"],
  CR: ["\r", "\r", "\r"],
  mixed: ["\n", "\r\n", "\r"],
};

for (const [name, breaks] of Object.entries(endings)) {
  const source = (rows: string[]): string => rows.map((row, index) => row + breaks[index % breaks.length]).join("");
  describe(`physical line endings: ${name}`, () => {
    it("normalizes fenced code inside a block quote", () => {
      expect(parser.parse(source(["> ```", "> a", "> b", "> ```"]))).toMatchObject({
        children: [{ type: "blockquote", children: [{ type: "code", value: "a\nb" }] }],
      });
    });

    it("normalizes fenced code inside a list item", () => {
      expect(parser.parse(source(["- ```", "  a", "  b", "  ```"]))).toMatchObject({
        children: [{ type: "list", children: [{ type: "listItem", children: [{ type: "code", value: "a\nb" }] }] }],
      });
    });

    it("normalizes a raw HTML block inside a block quote", () => {
      expect(parser.parse(source(["> <script>", "> a", "> b", "> </script>"]))).toMatchObject({
        children: [{ type: "blockquote", children: [{ type: "html", value: "<script>\na\nb\n</script>" }] }],
      });
    });

    it("preserves raw math body endings inside a list item", () => {
      expect(parser.parse(source(["- $$", "  a", "  b", "  $$"]))).toMatchObject({
        children: [{ type: "list", children: [{ type: "listItem", children: [{ type: "math", value: `a${breaks[1]}b` }] }] }],
      });
    });
  });
}

