import {build} from 'tsdown';
import {readFileSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
const root='/Users/zhilu/kazariex-projects/satorigear';
const extra=new Map([
 ['profile/features/heading.ts','atxMarkerEnd'],
 ['profile/features/blockquote.ts','blockQuoteOffset'],
 ['profile/features/html.ts','htmlStartAt'],
 ['profile/features/list.ts','listMarkerAt'],
].map(([file,name])=>[root+'/packages/satorigear/src/'+file,name]));
await build({config:false,cwd:root+'/packages/satorigear',entry:{'prototype-runtime':fileURLToPath(new URL('./runtime-entry.ts',import.meta.url))},outDir:fileURLToPath(new URL('./runtime/',import.meta.url)),clean:false,dts:false,exports:false,minify:false,outputOptions:{comments:false},plugins:[{name:'research-private-exports',load(id){if(extra.has(id))return readFileSync(id,'utf8')+'\nexport {'+extra.get(id)+'};\n'}}]});

