import{readFileSync,writeFileSync}from'node:fs';import{deepStrictEqual}from'node:assert';import{createHash}from'node:crypto';
const csp=process.argv.includes('--csp'),NativeFunction=globalThis.Function;
const examples=JSON.parse(readFileSync('test/corpus/commonmark.json','utf8')).map(x=>x.markdown),spec=readFileSync('test/corpus/commonmark-spec.md','utf8');
const sources=[];for(const ending of ['\n','\r\n','\r','mixed'])for(const input of [...examples,spec]){let i=0;sources.push(input.replace(/\r\n|\r|\n/g,ending==='mixed'?()=>['\n','\r\n','\r'][i++%3]:ending))}for(const file of ['rust-releases.md','public-apis.md'])sources.push(readFileSync('test/corpus/'+file,'utf8'));
if(csp)globalThis.Function=function(){throw new EvalError('CSP diagnostic')};
const baseline=(await import('./baseline.mjs')).createParser(),cases=sources.map(s=>baseline.parse(s)),reports={};
for(const file of ['uniform-original.mjs','dense-local-kernel.mjs','candidate.mjs']){const parser=(await import('./'+file)).createParser();for(let i=0;i<sources.length;i++)deepStrictEqual(parser.parse(sources[i]),cases[i]);reports[file]={sha256:createHash('sha256').update(readFileSync(new URL('./'+file,import.meta.url))).digest('hex'),cases:sources.length,completeAstAndPositionsEqual:true}}
globalThis.Function=NativeFunction;const result={csp,scope:'Default CommonMark only; extensions and createDocument not integrated',reports};writeFileSync(new URL(csp?'./variants-csp.json':'./variants-generated.json',import.meta.url),JSON.stringify(result,null,2)+'\n');console.log(result);

