import {readFileSync,writeFileSync}from'node:fs';import{pathToFileURL}from'node:url';import{resolve}from'node:path';import{performance}from'node:perf_hooks';import{Session}from'node:inspector';import{promisify}from'node:util';import{do_not_optimize}from'mitata';
const [file,out]=process.argv.slice(2),source=readFileSync('test/corpus/commonmark-spec.md','utf8'),parser=(await import(pathToFileURL(resolve(file)).href)).createParser();const run=()=>do_not_optimize(parser.parse(source));globalThis.gc();let t=performance.now();while(performance.now()-t<250)run();globalThis.gc();t=performance.now();while(performance.now()-t<150)run();const session=new Session;session.connect();const post=promisify(session.post).bind(session);await post('Profiler.enable');await post('Profiler.setSamplingInterval',{interval:100});await post('Profiler.start');t=performance.now();let count=0;while(performance.now()-t<300){run();count++}const elapsed=performance.now()-t;const {profile}=await post('Profiler.stop');session.disconnect();writeFileSync(out,JSON.stringify({count,elapsed,profile}));console.log({file,count,elapsed});
const nodes=new Map(profile.nodes.map(n=>[n.id,n])),hits=new Map;for(const id of profile.samples){const n=nodes.get(id),k=n.callFrame.functionName+':'+n.callFrame.lineNumber;hits.set(k,(hits.get(k)??0)+1)}console.log([...hits].sort((a,b)=>b[1]-a[1]).slice(0,22));

