for(const csp of[false,true]){const calls=[];globalThis.Function=function(...args){const text=args.at(-1);const kind=text.includes('return(s,row,o,p,c)')?'current-row block dispatch':text.includes('return s=>')?'inline tokenizer':'baseline block registration (unused by row scanner)';try{if(csp)throw new EvalError('CSP');const f=Reflect.apply(Native,undefined,args);calls.push({kind,success:true});return f}catch(e){calls.push({kind,success:false});throw e}};let parser;try{parser=current()}finally{globalThis.Function=Native}const source='[a]: /url

> **label** [a]

- one
- two
';deepStrictEqual(parser.parse(source),baseline().parse(source));results.push({csp,calls,publicParseAstPositionsEqual:true})}writeFileSync(new URL('./backend-activation.json',import.meta.url),JSON.stringify(results,null,2));console.log(results);

