sources.check-bundle.mjs:
import {readFileSync,writeFileSync} from 'node:fs';import {deepStrictEqual} from 'node:assert';import {createParser as baseline} from './baseline.mjs';import {createParser as candidate} from './candidate.mjs';
const NativeFunction=globalThis.Function,csp=process.argv.includes('--csp');if(csp)globalThis.Function=function(){throw new EvalError('CSP diagnostic')};const a=baseline(),b=candidate();globalThis.Function=NativeFunction;
const examples=JSON.parse(readFileSync('test/corpus/commonmark.json','utf8')).map(x=>x.markdown),spec=readFileSync('test/corpus/commonmark-spec.md','utf8');let cases=0;
for(const ending of ['
','
','','mixed'])for(const input of [...examples,spec]){let i=0;const source=input.replace(/
||
/g,ending==='mixed'?()=>['
','
',''][i++%3]:ending);deepStrictEqual(b.parse(source),a.parse(source));cases++}
for(const file of ['rust-releases.md','public-apis.md']){const source=readFileSync('test/corpus/'+file,'utf8');deepStrictEqual(b.parse(source),a.parse(source));cases++}
const result={csp,cases,completeAstAndPositionsEqual:true,profile:'Default CommonMark AST/positions; separate feature and edit guards'};writeFileSync(new URL(csp?'./bundle-csp-check.json':'./bundle-check.json',import.meta.url),JSON.stringify(result,null,2)+'
');console.log(result);

sources.count-events.mjs:
import{readFileSync,writeFileSync}from'node:fs';
const cases={'commonmark/spec':readFileSync('test/corpus/commonmark-spec.md','utf8'),'features/rust':readFileSync('test/corpus/rust-releases.md','utf8'),'features/apis':readFileSync('test/corpus/public-apis.md','utf8'),'attributes/hard-breaks':'> text  \n>  next\\\n> tail\n\n'.repeat(400)};
const features={footnote:true,frontmatter:true,math:true,strikethrough:true,table:true,taskList:true},report={diagnosticOnly:true,variants:{}};
for(const variant of ['baseline','candidate']){const{createParser}=await import('./'+variant+'-count.mjs');const results=report.variants[variant]={};for(const[name,source]of Object.entries(cases)){globalThis.eventCounts={regions:0,characters:0,boundaryCalls:0,dataFacts:0,kinds:{}};const parser=createParser({features:name.startsWith('commonmark/')?undefined:name.startsWith('attributes/')?{attributes:true}:features});parser.parse(source);results[name]=eventCounts}}
writeFileSync(new URL('./event-counts.json',import.meta.url),JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify(report,null,2));

