artifacts.scan-swar.js:
static #scan(source, lines) {
	const limit = source.length;
	let start = 0;
	let field = 0;
	let fields = lines.#fields;
	lines.#lineEndingsNormalized = true;
	while (start < limit) {
		let end = start;
		// Two UTF-16 lanes; zero-lane detection asks only whether either matches.
		while (end + 1 < limit) {
			const first = source.charCodeAt(end);
			const second = source.charCodeAt(end + 1);
			const word = first | (second << 16);
			const lf = word ^ 0x000a000a;
			const cr = word ^ 0x000d000d;
			const matches = (((lf - 0x00010001) & ~lf) | ((cr - 0x00010001) & ~cr)) & 0x80008000;
			if (matches !== 0) {
				if (first !== 10 && first !== 13) end++;
				break;
			}
			end += 2;
		}
		let code = source.charCodeAt(end);
		if (code !== 10 && code !== 13) end = limit;
		let next = end;
		if (end < limit) {
			next++;
			if (code === 13) {
				lines.#lineEndingsNormalized = false;
				if (source.charCodeAt(next) === 10) next++;
			}
		}
		if (field >= fields.length) {
			lines.#ensureCapacity(field + 4);
			fields = lines.#fields;
		}
		fields[field++] = start;
		fields[field++] = end;
		fields[field++] = next;
		fields[field++] = 0;
		start = next;
	}
	return field / 4;
}

