import {Buffer} from 'node:buffer';
import {writeFileSync} from 'node:fs';
const p=import.meta.dirname;const report={runtime:process.version,diagnosticOnly:true,results:{}};
const originalAlloc=Buffer.allocUnsafeSlow,originalSubarray=Buffer.prototype.subarray;
let counts,raws=new WeakSet();
Buffer.allocUnsafeSlow=function(size){const raw=originalAlloc(size);raws.add(raw);if(counts){counts.allocations++;counts.requestedBytes+=size;counts.offsets.push(raw.byteOffset);}return raw;};
Buffer.prototype.subarray=function(...args){if(counts&&raws.has(this))counts.subarrayViews++;return Reflect.apply(originalSubarray,this,args);};
try {
 for(const v of ['baseline','final']){
  const {BlockLines}=await import(new URL(v+'-export.mjs',import.meta.url));const lines=new BlockLines(0,0);
  counts={allocations:0,requestedBytes:0,subarrayViews:0,offsets:[]};
  for(const n of [2048,2049,2050,2051,2052,2053,2054,2055,8192,8193,2048])lines.scan('x'.repeat(n-1)+'\r');
  report.results[v]=counts;counts=undefined;
 }
}finally {Buffer.allocUnsafeSlow=originalAlloc;Buffer.prototype.subarray=originalSubarray;}
writeFileSync(p+'/allocation-counts.json',JSON.stringify(report,null,2));console.log(report);

