export function analyzeBlocks(runs: readonly Observation[]): {
  changePercent: number;
  ci95Percent: [number, number];
  blockChangesPercent: number[];
} {
  assert.ok(runs.length === 16 || runs.length === 32, "Use four or eight complete blocks");
