let memory,scan;try{({memory,scan}=new WebAssembly.Instance(new WebAssembly.Module(bytes)).exports)}catch{}
const encoder=new TextEncoder();
let encoded,output;
export function scanLines(source){
 if(!scan)return;
 const inputCapacity=source.length*3,outputBase=(inputCapacity+3)&~3,required=outputBase+4+(source.length+1)*16;
 if(required>memory.buffer.byteLength)memory.grow(Math.ceil((required-memory.buffer.byteLength)/65536));
 encoded=new Uint8Array(memory.buffer,0,inputCapacity);
