diagnosticSources.raw-locator.mjs:
class RawSourceLocator {
  #source;
  #normalized;
  #line = 1;
  #start = 0;
  #lf;
  #cr;
  constructor(source) {
    this.#source = source;
    this.#lf = source.indexOf('\n');
    this.#cr = source.indexOf('\r');
    this.#normalized = this.#cr < 0;
  }
  normalizeLineEndings(value) {
    return this.#normalized || !value.includes('\r') ? value : value.replace(/\r\n|\r/g,'\n');
  }
  locationAt(offset) {
    const source=this.#source;
    let lf=this.#lf,cr=this.#cr,line=this.#line,start=this.#start;
    while(true){
      const end=lf<0?cr:cr<0?lf:Math.min(lf,cr);
      if(end<0)break;
      const next=end+1+(end===cr&&source.charCodeAt(end+1)===10?1:0);
      if(next>offset)break;
      start=next;line++;
      if(lf>=0&&lf<next)lf=source.indexOf('\n',next);
      if(cr>=0&&cr<next)cr=source.indexOf('\r',next);
    }
    this.#lf=lf;this.#cr=cr;this.#line=line;this.#start=start;
    return {line,column:offset-start+1,offset};
  }
  positionAt(start,end){return {start:this.locationAt(start),end:this.locationAt(end)}}
}

