const starts=[0];for(let index=source.indexOf('\n');index>=0;index=source.indexOf('\n',index+1))starts.push(index+1);
const lower=(x)=>{let lo=0,hi=starts.length;while(lo<hi){const m=(lo+hi)>>>1;if(starts[m]<x)lo=m+1;else hi=m}return lo};
const scanner=new BlockScanner(compileProfile().block);scanner.scan(source);
let fences=0,rows=0,bodyRows=0;
for(let i=0;i<scanner.tokens.length;i++){
 const data=scanner.tokens.value(i);
 if(!data||typeof data!=='object'||!('closed' in data)||!('info' in data))continue;
 const start=scanner.tokens.start(i),end=scanner.tokens.end(i);
 let first=lower(start);if(starts[first]!==start)first--;
 const count=lower(end)-first;fences++;rows+=count;bodyRows+=Math.max(0,count-1-(data.closed?1:0));
}
const result={physicalRows:starts.length-1,fences,fenceSpanPhysicalRows:rows,fenceBodyPhysicalRows:bodyRows,profile:'CommonMark default',diagnosticOnly:true};
