import {readFileSync,writeFileSync} from 'node:fs';
import {deepStrictEqual} from 'node:assert';
import {createPrototype,UnsupportedSyntax} from './stream-prototype.mjs';
import {createParser} from './baseline.mjs';
const NativeFunction=globalThis.Function,csp=process.argv.includes('--csp');if(csp)globalThis.Function=function(){throw new EvalError('CSP diagnostic')};const baseline=createParser(),candidate=createPrototype();globalThis.Function=NativeFunction;
const examples=JSON.parse(readFileSync('test/corpus/commonmark.json','utf8'));let compatible=0;const unsupported=[],mismatches=[];
for(const ending of ['\n','\r\n','\r','mixed'])for(let i=0;i<examples.length;i++){
 let count=0;const source=examples[i].markdown.replace(/\r\n|\r|\n/g,ending==='mixed'?()=>['\n','\r\n','\r'][count++%3]:ending);
 try{const tree=candidate.parse(source);try{deepStrictEqual(tree,baseline.parse(source));compatible++}catch(error){mismatches.push({example:i+1,ending,source,error:String(error).slice(0,1300)})}}
 catch(error){if(error instanceof UnsupportedSyntax)unsupported.push({example:i+1,ending,section:examples[i].section,source,error:String(error)});else throw error}
}
const result={total:examples.length*4,officialExamples:examples.length,lineEndingVariants:4,csp,compatible,unsupported,acceptedMismatches:mismatches,noWholeGrammarOrPerformanceClaim:true};writeFileSync(new URL(csp?'./example-coverage-csp.json':'./example-coverage.json',import.meta.url),JSON.stringify(result,null,2)+'\n');console.log({total:result.total,compatible,unsupported:unsupported.length,mismatches:mismatches.length,firstMismatches:mismatches.slice(0,4)});if(mismatches.length)process.exitCode=1;

