import {readFileSync,writeFileSync} from 'node:fs';
import {deepStrictEqual} from 'node:assert';
import {createParser} from './baseline.mjs';
import {createPrototype} from './stream-prototype.mjs';
const NativeFunction=globalThis.Function,csp=process.argv.includes('--csp');
if(csp)globalThis.Function=function(){throw new EvalError('CSP diagnostic')};
const a=createParser(),b=createPrototype();globalThis.Function=NativeFunction;
const original=readFileSync('test/corpus/commonmark-spec.md','utf8'),results=[];
for(const ending of ['\n','\r\n','\r','mixed']){
 let index=0;const source=original.replace(/\r\n|\r|\n/g,ending==='mixed'?()=>['\n','\r\n','\r'][index++%3]:ending);
 const actual=b.parse(source),expected=a.parse(source),mismatches=[];
 for(let i=0;i<Math.max(actual.children.length,expected.children.length);i++)try{deepStrictEqual(actual.children[i],expected.children[i])}catch(error){mismatches.push({index:i,actual:actual.children[i],expected:expected.children[i],error:String(error).slice(0,1500)})}
 try{deepStrictEqual(actual.position,expected.position)}catch(error){mismatches.push({rootPosition:String(error)})}
 results.push({ending,sourceLength:source.length,actualRoots:actual.children.length,baselineRoots:expected.children.length,mismatchCount:mismatches.length,mismatches:mismatches.slice(0,5),diagnostic:b.diagnostic});
}
writeFileSync(new URL(csp?'./whole-spec-csp-check.json':'./whole-spec-check.json',import.meta.url),JSON.stringify({csp,results},null,2)+'\n');
console.log(results.map(({mismatches,...rest})=>({...rest,firstMismatch:mismatches[0]?.error})));if(results.some(x=>x.mismatchCount))process.exitCode=1;

